<?php foreach($snapshot['questions'] as $i=>$q): ?><fieldset class="eh-question"><legend><?php echo ($i+1).'. '.html_escape($q['prompt']); ?></legend><?php if($q['type']==='choice'): foreach($q['options'] as $j=>$option): ?><label class="eh-choice"><input type="radio" name="answers[<?php echo html_escape($q['id']); ?>]" value="<?php echo $j; ?>" <?php echo isset($submitted[$q['id']])&&is_string($submitted[$q['id']])&&$submitted[$q['id']] === (string)$j?'checked':''; ?> required><span><?php echo html_escape($option); ?></span></label><?php endforeach; else: ?><label for="answer-<?php echo html_escape($q['id']); ?>" class="eh-small">Jawaban singkat</label><input id="answer-<?php echo html_escape($q['id']); ?>" name="answers[<?php echo html_escape($q['id']); ?>]" value="<?php echo html_escape(isset($submitted[$q['id']])&&is_string($submitted[$q['id']])?$submitted[$q['id']]:''); ?>" maxlength="500" autocomplete="off" required><?php endif; ?></fieldset><?php endforeach; ?>
<button class="eh-btn eh-btn-gold" type="submit">Kirim & lihat pembahasan</button><?php echo form_close(); ?><?php endif; ?><?php endif; ?>
